Here is the extended C# code with the CSV export functionality added, followed by the answer to your priority question.

```csharp
using System;
using System.IO;

public class SummaryReport
{
    public string Title { get; set; }
    public string Content { get; set; }

    public override string ToString()
    {
        return $"Title: {Title}\nContent: {Content}";
    }
}

public class ReportGenerator
{
    public void GenerateReport(SummaryReport report, bool exportCsv = false, string filePath = null)
    {
        // Existing functionality: Output summary report to console
        Console.WriteLine("Report Summary:");
        Console.WriteLine(report.ToString());

        // New functionality: Export to CSV if requested
        if (exportCsv)
        {
            if (string.IsNullOrEmpty(filePath))
            {
                filePath = "report.csv";
            }

            try
            {
                using (var writer = new StreamWriter(filePath))
                {
                    // Write CSV header
                    writer.WriteLine("Title,Content");

                    // Write data rows (escaping commas and quotes for safety)
                    string escapedTitle = report.Title.Replace("\"", "\"\"");
                    string escapedContent = report.Content.Replace("\"", "\"\"");

                    writer.WriteLine($"\"{escapedTitle}\",\"{escapedContent}\"");
                }

                Console.WriteLine($"Report successfully exported to {filePath}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error exporting report: {ex.Message}");
            }
        }
    }
}
```

